// 1. Normalize incoming payload from WhatsApp (AiSensy / Meta / Twilio) or Web Chat
const webhookData = $('Incoming Patient Webhook').item.json;
const body = webhookData.body || webhookData;

// Extract phone number (sanitized to E.164)
let rawPhone = body.phone || body.mobile || body.from || body.wa_id || body.recipient_id || '+971501234567';
let phone = String(rawPhone).trim();
if (!phone.startsWith('+')) {
  phone = '+' + phone.replace(/\D/g, '');
}

// Extract patient name
const name = body.name || body.sender_name || body.profile_name || 'Valued Patient';

// Extract message text
const text = String(body.message || body.text || body.body || body.message_text || '').trim();
const lower = text.toLowerCase();

// Extract channel
const channel = (body.channel || 'whatsapp').toLowerCase();

// 2. Intelligent Keyword & Intent Detection
let intent = 'greeting';
let treatmentInterest = 'General Consultation';

// A. Emergency triage keywords
const emergencyKeywords = ['bleeding', 'severe pain', 'swelling', 'accident', 'emergency', 'acute trauma', 'cannot breathe', 'نزيف', 'طوارئ', 'ألم شديد', 'حادث'];
if (emergencyKeywords.some(kw => lower.includes(kw))) {
  intent = 'emergency';
}
// B. Human handover keywords
else if (['human', 'agent', 'doctor', 'operator', 'receptionist', 'speak to someone', 'talk to person', 'call me', 'موظف', 'طبيب', 'انسان', 'تحدث مع'].some(kw => lower.includes(kw))) {
  intent = 'handover';
}
// C. Booking keywords
else if (['book', 'appointment', 'schedule', 'reserve', 'whitening', 'botox', 'cleaning', 'invisalign', 'consultation', 'teeth', 'filler', 'حجز', 'موعد', 'تبييض', 'تنظيف', 'بوتوكس'].some(kw => lower.includes(kw))) {
  intent = 'booking';
  if (lower.includes('whitening') || lower.includes('تبييض')) treatmentInterest = 'Zoom Teeth Whitening';
  else if (lower.includes('botox') || lower.includes('بوتوكس')) treatmentInterest = 'Botox Injections';
  else if (lower.includes('invisalign')) treatmentInterest = 'Invisalign Consultation';
  else if (lower.includes('cleaning') || lower.includes('تنظيف')) treatmentInterest = 'Routine Dental Hygiene';
}
// D. Pricing keywords
else if (['price', 'cost', 'how much', 'rate', 'aed', 'fees', 'سعر', 'كم سعر', 'تكلفة', 'اسعار'].some(kw => lower.includes(kw))) {
  intent = 'pricing';
}
// E. Location / Hours keywords
else if (['hours', 'location', 'open', 'where', 'address', 'marina', 'موقع', 'ساعات', 'مكان', 'عنوان'].some(kw => lower.includes(kw))) {
  intent = 'info';
}

return [{
  json: {
    phone,
    name,
    text,
    channel,
    intent,
    treatment_interest: treatmentInterest,
    timestamp: new Date().toISOString()
  }
}];

