const booking = $input.first().json;
const lead = $('Normalize & Parse Message').item.json;
const slotData = $('Get Available Slots').item.json.slots[0];
const leadId = $('Upsert Lead in CRM').item.json.lead_id;

const dateObj = new Date(slotData.start);
const dateFormatted = dateObj.toLocaleDateString('en-GB', { weekday: 'long', year: 'numeric', month: 'short', day: 'numeric' });
const timeFormatted = dateObj.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' });

const replyText = `✅ APPOINTMENT CONFIRMED!\n\nDear ${lead.name},\nYour appointment has been successfully scheduled at Demo Dental & Aesthetic Clinic.\n\n📅 Date: ${dateFormatted}\n⏰ Time: ${timeFormatted} (Gulf Standard Time)\n🦷 Treatment: ${lead.treatment_interest}\n📍 Location: Dubai Marina Walk, Building 4 (Free Valet Parking)\n\nTo reschedule or inquire about insurance, reply directly to this message. We look forward to welcoming you!`;

return [{
  json: {
    lead_id: leadId,
    phone: lead.phone,
    name: lead.name,
    intent: lead.intent,
    text: lead.text,
    reply_text: replyText,
    action: 'appointment_booked',
    appointment_id: booking.appointment_id,
    appointment_date: `${dateFormatted} at ${timeFormatted}`
  }
}];

